#!/usr/bin/env node
// Writes manifest.json and config.js from project.toml.
//
//   node generate-manifest.mjs           write both files
//   node generate-manifest.mjs --check   fail when they are out of date
//
// The manifest's "key" pins the unpacked extension's ID to project.toml's
// dev_id on every machine, which is what the native host's allowed_origins
// lists. The generated files are committed so the folder loads as-is in
// "Load unpacked"; rerun this after editing project.toml.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { readProject } from "./project-config.mjs";

const here = dirname(fileURLToPath(import.meta.url));

const EXTENSION_VERSION = "0.1.0";
// TODO(gustavo): move to project.toml once the app's release numbering exists.
const MIN_APP_VERSION = "0.1.0";
const PAGES = ["http://localhost/*", "http://127.0.0.1/*"];

export function buildFiles(project = readProject()) {
  const manifest = {
    manifest_version: 3,
    name: `${project.productName} (probe extension)`,
    version: EXTENSION_VERSION,
    description:
      "Test extension for the native messaging proofs. Bridges pages on localhost to the native host.",
    key: project.devKey,
    minimum_chrome_version: "121",
    permissions: ["nativeMessaging"],
    background: {
      service_worker: "background.js",
      scripts: ["config.js", "native-host.js", "background.js"],
    },
    content_scripts: [
      { matches: PAGES, js: ["content.js"], run_at: "document_start" },
    ],
    browser_specific_settings: {
      gecko: {
        id: project.firefoxId,
        strict_min_version: "121.0",
        // Nothing the extension handles leaves the machine but the digest,
        // which goes to the local app only.
        data_collection_permissions: { required: ["none"] },
      },
    },
  };
  const config = {
    nativeHost: project.nativeHost,
    minAppVersion: MIN_APP_VERSION,
    pages: PAGES,
  };
  return {
    "manifest.json": `${JSON.stringify(manifest, null, 2)}\n`,
    "config.js":
      "// Generated by generate-manifest.mjs from project.toml. Do not edit.\n" +
      `globalThis.WEBSIGN_CONFIG = Object.freeze(${JSON.stringify(config, null, 2)});\n`,
  };
}

function main() {
  const files = buildFiles();
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [name, text] of Object.entries(files)) {
    const path = join(here, name);
    if (check) {
      let current = "";
      try {
        current = readFileSync(path, "utf8");
      } catch {}
      if (current !== text) {
        console.error(`${name} is out of date; run: node generate-manifest.mjs`);
        stale += 1;
      }
    } else {
      writeFileSync(path, text);
    }
  }
  process.exit(stale === 0 ? 0 : 1);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
